// Video Studio film. Generated by pipeline/render/reelkit.mjs from the episode files:
// EPISODE below holds this film's frames, words, palette and media paths; the shot components come from
// episodes/<date>/shots/*.tsx (the reelkit skill) and canvas shots arrive as rendered clips (the animate-in-code
// skill). Edit this template (pipeline/render/reelkit/Video.tsx), never the copy in episodes/*/reelkit/src/.
import React from "react";
import { AbsoluteFill, Audio, Img, Sequence, interpolate, delayRender, continueRender } from "reelkit/frame";
import { ease, font } from "reelkit/kit";
import type { VideoProps } from "reelkit/kit";
import { At } from "./At";
import { BigText, bidi } from "./BigText";
import { Bot } from "./Bot";
import { Bubble } from "./Bubble";
import { Card } from "./Card";
import { CountUp } from "./CountUp";
import { Doodle } from "./Doodle";
import { FocusBackdrop } from "./FocusBackdrop";
import { GlowText } from "./GlowText";
import { LightBurst } from "./LightBurst";
import { Paper } from "./Paper";
import { Phone } from "./Phone";
import { Photo } from "./Photo";
import { Pop } from "./Pop";
import { PopImage } from "./PopImage";
import { PopMotion } from "./PopMotion";
import { Progress } from "./Progress";
import { Reveal } from "./Reveal";
import { SelectBox } from "./SelectBox";
import { ShotClip } from "./ShotClip";
import { Stamp } from "./Stamp";
import { StatPop } from "./StatPop";
import { Subtitles } from "./Subtitles";
import { Tag } from "./Tag";
import { TickGrid } from "./TickGrid";
import { Toggle } from "./Toggle";
import { TypeField } from "./TypeField";
import { VoiceLine } from "./VoiceLine";
import { Window } from "./Window";
import type { CaptionGroup } from "./Subtitles";
import type { StatCount } from "./StatPop";
// @shot-imports (filled in by pipeline/render/reelkit.mjs)

// The shared visual vocabulary every shot draws with. Reelkit lets only Video.tsx import sibling files, so the
// shots (episodes/<date>/shots/*.tsx, self-contained) receive it as the `ui` prop: `const { Pop, BigText } = ui;`.
// `prog(frame, at, len)` = eased 0→1 progress of a move starting on a cue; `bidi(text)` isolates Latin runs in Hebrew.
const prog = (frame: number, at: number, len = 12, easing: (t: number) => number = ease.out) =>
  interpolate(frame, [at, at + Math.max(1, len)], [0, 1], { easing, extrapolateLeft: "clamp", extrapolateRight: "clamp" });
const UI = { At, BigText, Bot, Bubble, Card, CountUp, Doodle, Img, Phone, Photo, Pop, Progress, SelectBox, Stamp, Tag, TickGrid, Toggle, TypeField, Window, prog, bidi };
export type Ui = typeof UI;

export type Palette = { bg: string; ink: string; accent: string; accentInk: string; muted: string; paper: string; [name: string]: string };
// What every shot component receives (episodes/<date>/shots/<Name>.tsx: `export const Name = (p: ShotProps) => …`).
export type ShotProps = {
  id: string;
  // Length of the shot in frames, and the frame rate.
  frames: number;
  fps: number;
  // Frame inside the shot at which each cue's word is spoken (shots.json → cues).
  cue: Record<string, number>;
  // Every word spoken during the shot, with its first and last frame inside the shot.
  words: { word: string; f: number; end: number }[];
  // The day's concept palette, the display and body font families, the shot's prepared images.
  c: Palette;
  face: string;
  body: string;
  img: Record<string, { src: string; w: number; h: number }>;
  ui: Ui;
};

type Shot = {
  id: string; kind: "component" | "clip"; component?: string; src?: string; under?: string; from: number; frames: number;
  cue: Record<string, number>; words: { word: string; f: number; end: number }[]; images: string[]; motif: boolean;
};
type Overlay = {
  id: string; type: "logo" | "image" | "icon" | "stat" | "title"; from: number; frames: number; in: string; out: string; x: number; y: number;
  src?: string; w?: number; h?: number; text?: string; count?: StatCount | null; label?: string | null; subtitle?: string | null; size?: number; labelSize?: number; focus?: boolean;
};
type Episode = {
  fps: number; width: number; height: number; totalFrames: number;
  palette: Palette;
  faces: { display: string; body: string };
  // Font files the project brought (Google Fonts for scripts the kit does not cover: Arabic, Cyrillic, CJK, Devanagari…).
  customFonts: { family: string; src: string; weight?: string }[];
  ground: { grain: number; pattern: "none" | "dots" | "grid" | "lines"; patternColor: string };
  motif: { type: "voiceline" | "none"; y: number; amp: number; color: string; outline: string; levels: number[]; spans: { from: number; to: number }[] };
  shots: Shot[];
  images: Record<string, { src: string; w: number; h: number }>;
  overlays: Overlay[];
  captions: { groups: CaptionGroup[]; size: number; bottom: number; ink: string; chip: string; chipInk: string; plate: string | null; halo: string | null } | null;
  audio: { voice: string; music: string | null; musicVolume: number; sfx: { src: string; at: number; frames: number; volume: number }[] };
  look: { focusBlur: number; focusDim: number };
};

const EPISODE: Episode = {} as Episode; // filled in by pipeline/render/reelkit.mjs
const SHOTS: Record<string, React.FC<ShotProps>> = {}; // @shots (filled in by pipeline/render/reelkit.mjs)

const palette = EPISODE.palette;
// A face is a kit font name ("heebo", "bebasNeue"…) or the family of one of the project's customFonts.
const custom = new Set((EPISODE.customFonts ?? []).map((f) => f.family));
const face = (name: string) => (custom.has(name) ? `"${name}", ${font("heebo")}` : font(name as Parameters<typeof font>[0]));
const display = face(EPISODE.faces.display);
const body = face(EPISODE.faces.body);

// Loads the project's font files before the first frame is drawn.
const useCustomFonts = (urls: Record<string, string>) => {
  const [handle] = React.useState(() => ((EPISODE.customFonts ?? []).length ? delayRender("custom fonts") : null));
  React.useEffect(() => {
    if (handle === null) return;
    Promise.all((EPISODE.customFonts ?? []).map(async (f) => {
      const ff = new FontFace(f.family, `url(${urls[f.src]})`, { weight: f.weight ?? "400" });
      document.fonts.add(await ff.load());
    })).catch((err) => console.error(`custom font failed: ${err}`)).finally(() => continueRender(handle));
  }, [handle, urls]);
};

export const Video: React.FC<VideoProps> = ({ urls }) => {
  const e = EPISODE;
  useCustomFonts(urls);
  const imgs = (ids: string[]) => Object.fromEntries(ids.map((id) => [id, { ...e.images[id], src: urls[e.images[id].src] }]));
  return (
    <AbsoluteFill style={{ backgroundColor: palette.bg }}>
      <Paper color={palette.bg} grain={e.ground.grain} pattern={e.ground.pattern} patternColor={e.ground.patternColor} />
      <FocusBackdrop windows={e.overlays.filter((o) => o.focus)} blur={e.look.focusBlur} dim={e.look.focusDim}>
        {e.shots.map((s) => {
          const Comp = s.component ? SHOTS[s.component] : undefined;
          return (
            <Sequence key={s.id} from={s.from} durationInFrames={s.frames}>
              {s.kind === "clip" ? (
                <ShotClip kind="video" src={urls[s.src ?? ""]} />
              ) : Comp ? (
                <>
                  {s.under ? <ShotClip kind="video" src={urls[s.under]} /> : null}
                  <Comp id={s.id} frames={s.frames} fps={e.fps} cue={s.cue} words={s.words} c={palette} face={display} body={body} img={imgs(s.images)} ui={UI} />
                </>
              ) : null}
            </Sequence>
          );
        })}
      </FocusBackdrop>

      {e.motif.type === "voiceline"
        ? e.motif.spans.map((sp) => (
            <Sequence key={`motif-${sp.from}`} from={sp.from} durationInFrames={sp.to - sp.from}>
              <VoiceLine levels={e.motif.levels.slice(sp.from)} y={e.motif.y} amp={e.motif.amp} color={e.motif.color} outline={e.motif.outline} />
            </Sequence>
          ))
        : null}

      {e.overlays.map((o) => (
        <Sequence key={o.id} from={o.from} durationInFrames={o.frames}>
          {o.focus ? (
            <div style={{ position: "absolute", left: `${o.x * 100}%`, top: `${o.y * 100}%`, width: 0, height: 0 }}>
              <LightBurst color={palette.accent} />
            </div>
          ) : null}
          <PopMotion frames={o.frames} enter={o.in} exit={o.out} x={o.x} y={o.y}>
            {o.type === "stat" ? (
              <StatPop text={o.text ?? ""} count={o.count} ink={palette.ink} glow={palette.accent} face={display} size={o.size}>
                {o.label ? (
                  <Reveal delay={8}>
                    <GlowText text={o.label} ink={palette.ink} glow={palette.accent} face={display} size={o.labelSize} weight={800} strength={0.35} />
                  </Reveal>
                ) : null}
              </StatPop>
            ) : o.type === "title" ? (
              <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
                <GlowText text={o.text ?? ""} ink={palette.ink} glow={palette.accent} face={display} size={o.size} />
                {o.subtitle ? (
                  <Reveal delay={8}>
                    <GlowText text={o.subtitle} ink={palette.ink} glow={palette.accent} face={display} size={o.labelSize} weight={800} strength={0.35} />
                  </Reveal>
                ) : null}
              </div>
            ) : (
              <PopImage src={urls[o.src ?? ""]} w={o.w ?? 0} h={o.h ?? 0} shadow={o.type !== "icon"} />
            )}
          </PopMotion>
        </Sequence>
      ))}

      {e.captions ? (
        <Subtitles groups={e.captions.groups} ink={e.captions.ink} chip={e.captions.chip} chipInk={e.captions.chipInk} face={display} size={e.captions.size} bottom={e.captions.bottom} plate={e.captions.plate} halo={e.captions.halo} />
      ) : null}

      <Audio src={urls[e.audio.voice]} volume={1} />
      {e.audio.music ? <Audio src={urls[e.audio.music]} volume={e.audio.musicVolume} /> : null}
      {e.audio.sfx.map((x, i) => (
        <Sequence key={`sfx-${i}`} from={x.at} durationInFrames={x.frames} layout="none">
          <Audio src={urls[x.src]} volume={x.volume} />
        </Sequence>
      ))}
    </AbsoluteFill>
  );
};
